using FluentAssertions; using Sigov.Domain.Agro; using Sigov.Domain.Agro.Enums; using Xunit;
namespace Sigov.UnitTests.Agro; public sealed class AgroManutencaoRuralRulesTests{[Fact] public void Manutencao_executada_exige_data()=>FluentActions.Invoking(()=>new ManutencaoRural(1,1,2026,"M1","PATROLAMENTO","Desc",AgroManutencaoRuralStatus.EXECUTADA)).Should().Throw<ArgumentException>(); [Fact] public void Custo_negativo_falha()=>FluentActions.Invoking(()=>new ManutencaoRural(1,1,2026,"M1","PATROLAMENTO","Desc",AgroManutencaoRuralStatus.PROGRAMADA,null,-1)).Should().Throw<ArgumentException>();}
